export function installCommunityWalk({pause,rewards,stops,routes=[],getLounges=()=>[]}){
 const walks=[{id:'community',name:'The Community Walk',description:'Explore places shaped by Krownlandia’s community and history. Follow the suggested order or choose any stop. Your existing activity progress counts.',stops},...routes];let selected=walks[0],revision=0;
 const dialog=document.createElement('dialog');dialog.id='communityWalk';dialog.setAttribute('aria-labelledby','communityWalkTitle');
 const title=document.createElement('h2');title.id='communityWalkTitle';title.textContent='The Community Walk';
 const intro=document.createElement('p');intro.textContent='Explore five places shaped by Krownlandia’s community and history. Follow the suggested order or choose any stop. Your existing activity progress counts.';
 const progress=document.createElement('p');progress.id='communityWalkProgress';progress.setAttribute('aria-live','polite');const body=document.createElement('div');body.id='communityWalkStops';
 function button(label,id,action,accessibleName){const b=document.createElement('button');b.id=id;b.textContent=label;if(accessibleName)b.setAttribute('aria-label',accessibleName);b.onclick=()=>{if(b.disabled||(id!=='communityWalkButton'&&!dialog.open))return;return action();};return b;}
 function resultButton(label,id,action,accessibleName){const rendered=revision;return button(label,id,()=>{if(rendered!==revision)return;return action();},accessibleName);}
 const guide=stop=>{pause();rewards.guideToPoint({...stop.point,name:stop.name});dialog.close();};
 const next=button('Guide me to the next activity','communityWalkNext',()=>{const done=rewards.state().done,stop=stops.find(s=>!done.includes(s.task));if(stop)guide(stop);});
 const guideRewards=stop=>{pause();rewards.guideTo(stop.id);dialog.close();};
 const readyStops=state=>stops.filter(s=>state.done.includes(s.task)&&!state.claims.includes(s.id+':task'));
 const ready=button('Find a reward ready to claim','communityWalkReady',()=>{const stop=readyStops(rewards.state())[0];if(stop)guideRewards(stop);});
 const rewardSummary=document.createElement('p');rewardSummary.id='communityWalkRewards';rewardSummary.setAttribute('aria-live','polite');
 const choices=document.createElement('div');choices.id='communityWalkRoutes';choices.setAttribute('aria-label','Choose a discovery walk');const routeButtons=[];for(const route of walks){const b=button(route.name,'communityWalkRoute-'+route.id,()=>{selected=route;stops=route.stops;rest.open=false;render();});routeButtons.push(b);choices.append(b);}choices.hidden=walks.length<2;
 let unfinishedOnly=false,readyOnly=false;const filter=button('Unfinished activities','communityWalkUnfinished',()=>{unfinishedOnly=!unfinishedOnly;readyOnly=false;render();});filter.setAttribute('aria-pressed','false');
 const readyFilter=button('Ready rewards','communityWalkReadyFilter',()=>{readyOnly=!readyOnly;unfinishedOnly=false;render();});readyFilter.setAttribute('aria-pressed','false');const filters=document.createElement('div');filters.id='communityWalkFilters';filters.setAttribute('role','group');filters.setAttribute('aria-label','Filter walk stops');filters.append(filter,readyFilter);
 const rest=document.createElement('details');rest.id='communityWalkRest';const restTitle=document.createElement('summary');restTitle.textContent='Rest along this walk';const restList=document.createElement('div');rest.append(restTitle,restList);
 function renderRest(){restList.replaceChildren();const matches=getLounges().filter(s=>stops.some(stop=>stop.id===s.id));rest.hidden=matches.length===0;for(const s of matches){const p=document.createElement('p');p.textContent=s.snack+' · '+s.souvenir;const walk=resultButton('Walk to '+s.name,'communityWalkLounge-'+s.id,()=>{if(!dialog.open||!stops.some(stop=>stop.id===s.id))return;pause();rewards.guideToPoint({x:s.x,z:s.z+1.3,name:s.name});dialog.close();});restList.append(walk,p);}}
 const close=button('Back to the world','communityWalkClose',()=>{pause();dialog.close();});dialog.append(title,choices,intro,progress,next,rewardSummary,ready,rest,filters,body,close);document.body.append(dialog);
 const style=document.createElement('link');style.rel='stylesheet';style.href='community-walk.css';document.head.append(style);
 function render(){revision++;renderRest();const state=rewards.state(),done=state.done,count=stops.filter(s=>done.includes(s.task)).length;progress.textContent=count+' / '+stops.length+' activities completed · '+(state.saved?'saved progress':'this visit only');const unclaimed=readyStops(state).length;ready.hidden=unclaimed===0;ready.disabled=unclaimed===0;rewardSummary.textContent=unclaimed?unclaimed+' completed '+(unclaimed===1?'activity has':'activities have')+' a task reward ready to claim.':'No completed activity rewards waiting to be claimed.';next.disabled=count===stops.length;next.textContent=next.disabled?'Walk complete · revisit any stop':'Guide me to the next activity';filter.setAttribute('aria-pressed',String(unfinishedOnly));readyFilter.setAttribute('aria-pressed',String(readyOnly));body.replaceChildren();stops.forEach((stop,i)=>{if(unfinishedOnly&&done.includes(stop.task))return;if(readyOnly&&(!done.includes(stop.task)||state.claims.includes(stop.id+':task')))return;const card=document.createElement('article'),heading=document.createElement('h3'),text=document.createElement('p'),credit=document.createElement('p'),status=document.createElement('p');heading.textContent=(i+1)+'. '+stop.name;text.textContent=stop.description;credit.textContent=stop.credit;credit.className='walk-credit';status.id='communityWalkStatus-'+stop.id;status.textContent=(state.claims.includes(stop.id+':arrival')?'Arrival points collected':'Arrival points not yet claimed')+' · '+(state.claims.includes(stop.id+':task')?'Task reward collected':done.includes(stop.task)?'Task reward ready to claim':'Activity to explore');card.append(heading,text,credit,status,resultButton('Walk here','communityWalkGo-'+stop.id,()=>guide(stop),'Walk to '+stop.name),resultButton('Find rewards station','communityWalkReward-'+stop.id,()=>guideRewards(stop),'Find rewards station for '+stop.name));body.append(card);});if((unfinishedOnly&&count===stops.length)||(readyOnly&&unclaimed===0)){const empty=document.createElement('p');empty.id='communityWalkEmpty';empty.textContent=readyOnly?'No task rewards are ready on this walk. Turn off Ready rewards to explore its activities.':'All activities on this walk are complete. Turn off Unfinished activities to revisit any stop. Ready rewards remain available above.';body.append(empty);}const note=document.createElement('p');note.textContent='Claim available activity points at each location’s rewards station. The walk uses those existing activities and rewards.';body.append(note);}
 const renderStops=render;render=()=>{title.textContent=selected.name;intro.textContent=selected.description;const state=rewards.state();routeButtons.forEach((b,i)=>{const route=walks[i],completed=route.stops.filter(s=>state.done.includes(s.task)).length,readyCount=route.stops.filter(s=>state.done.includes(s.task)&&!state.claims.includes(s.id+':task')).length;b.setAttribute('aria-pressed',String(route===selected));b.textContent=route.name+' · '+completed+'/'+route.stops.length+' activities complete'+(readyCount?' · '+readyCount+' task '+(readyCount===1?'reward':'rewards')+' ready':'');});renderStops();};
 const nav=button('Community Walk','communityWalkButton',()=>{if(dialog.open){render();return;}pause();rest.open=false;render();dialog.showModal();});document.querySelector('nav').append(nav);
 return {get stops(){return stops},get route(){return selected.id},get isOpen(){return dialog.open}};
}
